// Domain object — zero knowledge of persistence
class User {
  constructor(public id: string, public email: string, public loyaltyPoints: number) {}
  calculateLoyaltyTier(): string {
    return this.loyaltyPoints > 1000 ? "gold" : "standard";
  }
}

// All persistence knowledge lives here instead
class UserMapper {
  async save(user: User): Promise<void> {
    await db.query("UPDATE users SET email=$1, loyalty_points=$2 WHERE id=$3", [user.email, user.loyaltyPoints, user.id]);
  }
  async find(id: string): Promise<User> {
    const row = await db.query("SELECT * FROM users WHERE id=$1", [id]);
    return new User(row.id, row.email, row.loyalty_points);
  }
}

